package com.haolin.vontlocal;
import android.app.*;import android.os.*;import android.text.*;import android.view.*;import android.view.inputmethod.*;import android.widget.*;

public final class FocusSettingsActivity extends Activity {
    Ui u;EditText work,rest,brightness,temperature;boolean dirty;TextView message;
    @Override public void onCreate(Bundle b){Ui.prepare(this);super.onCreate(b);u=new Ui(this);FocusPolicy.Settings s=FocusStore.settings(this);LinearLayout root=u.root(this);u.toolbar(this,root,"办公 · 提醒休息","保存参数后，由你确认开始");LinearLayout body=u.scrollBody(root);LinearLayout time=u.card(body);u.text(time,"工作与休息",21);work=field(time,"工作时长","专注工作分钟",s.workMinutes,1,60,"分钟");rest=field(time,"休息时长","专注休息分钟",s.restMinutes,1,60,"分钟");u.hint(time,"初始节奏：工作50分钟，休息5分钟，持续循环。");LinearLayout lamp=u.card(body);u.text(lamp,"休息时的挂灯",21);brightness=field(lamp,"亮度","专注休息亮度",s.restBrightness,1,100,"%");temperature=field(lamp,"色温","专注休息色温",s.restTemperature,2700,6500,"K");u.hint(lamp,"阶段切换时短暂柔和光变。复工时恢复本次开始的办公灯光。");LinearLayout help=u.card(body);u.text(help,"随时结束，灯光保留",19);u.hint(help,"单独结束只停止提醒；睡前、床上和全关会结束提醒并执行所选场景。取消开始确认不会改变任何灯光或计时。");u.hint(help,"这版由手机后台执行自定义光变，需要保持局域网连接。被系统中断后需手动重新开始；锁屏与实际提醒效果留待真机验证。");message=u.hint(body,"保存只影响下次开始，不改变正在运行的专注。");LinearLayout footer=u.column();footer.setPadding(u.dp(this,20),u.dp(this,8),u.dp(this,20),u.dp(this,12));u.button(footer,"保存提醒参数",this::save,true);root.addView(footer);
        if(b!=null){work.setText(b.getString("w",work.getText().toString()));rest.setText(b.getString("r",rest.getText().toString()));brightness.setText(b.getString("b",brightness.getText().toString()));temperature.setText(b.getString("k",temperature.getText().toString()));dirty=b.getBoolean("dirty");}else dirty=false;}
    EditText field(LinearLayout parent,String name,String desc,int value,int low,int high,String unit){LinearLayout row=u.row();row.addView(u.label(name,16,u.text),new LinearLayout.LayoutParams(0,-2,1));EditText e=new EditText(this);e.setTextSize(18);e.setSingleLine(true);e.setSelectAllOnFocus(true);e.setTextColor(u.accent);e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setImeOptions(EditorInfo.IME_ACTION_DONE);e.setContentDescription(desc);e.setText(String.valueOf(value));row.addView(e,new LinearLayout.LayoutParams(u.dp(this,100),u.dp(this,50)));row.addView(u.label(" "+unit,13,u.muted));parent.addView(row);SeekBar slider=new SeekBar(this);slider.setMax(high-low);slider.setProgress(value-low);slider.setContentDescription(desc+"滑块");parent.addView(slider,new LinearLayout.LayoutParams(-1,u.dp(this,48)));u.styleTree(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar v){}public void onStopTrackingTouch(SeekBar v){}public void onProgressChanged(SeekBar v,int n,boolean user){if(user)e.setText(String.valueOf(n+low));}});e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void afterTextChanged(Editable s){}public void onTextChanged(CharSequence s,int a,int c,int f){dirty=true;try{int n=Integer.parseInt(s.toString());if(n>=low&&n<=high)slider.setProgress(n-low);}catch(Exception ignored){}}});e.setOnEditorActionListener((v,id,event)->{if(id==EditorInfo.IME_ACTION_DONE){((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(e.getWindowToken(),0);e.clearFocus();return true;}return false;});return e;}
    void save(){try{FocusStore.saveSettings(this,new FocusPolicy.Settings(value(work,1,60),value(rest,1,60),value(brightness,1,100),value(temperature,2700,6500)));dirty=false;Toast.makeText(this,"提醒参数已保存，下次开始时使用",0).show();finish();}catch(IllegalArgumentException e){message.setText(e.getMessage());}}
    int value(EditText e,int low,int high){try{return LinkPolicy.integer(e.getText().toString(),low,high);}catch(IllegalArgumentException x){e.setError(x.getMessage());throw x;}}
    @Override public void onSaveInstanceState(Bundle b){b.putString("w",work.getText().toString());b.putString("r",rest.getText().toString());b.putString("b",brightness.getText().toString());b.putString("k",temperature.getText().toString());b.putBoolean("dirty",dirty);super.onSaveInstanceState(b);}
    @Override public void onBackPressed(){if(!dirty){super.onBackPressed();return;}new AlertDialog.Builder(this).setTitle("提醒参数尚未保存").setNegativeButton("继续编辑",null).setPositiveButton("放弃修改",(d,w)->finish()).show();}
}
